"""Report trial rigid alignment and its spatially separate LAS control."""
import json
import numpy as np
from check_las_rigid import OUT,DATES


def main():
    audit=json.loads((OUT/'audit.json').read_text());rows=audit['comparison'];chosen=audit['chosen']
    def metric(date,method,region='bank_south'):
        return next(r for r in rows if r['date']==date and r['method']==method and r['region']==region)
    worse=[d for d in DATES[:-1] if metric(d,'rigid_trial')['symmetric_median_m']>metric(d,'original')['symmetric_median_m']]
    all_better=[d for d in DATES[:-1] if all(metric(d,'rigid_trial')[k]<metric(d,'original')[k] for k in ['symmetric_median_m','source_p90_m','target_p90_m'])]
    lines=['# LAS между датами: проверка поворота и сдвига','',
        '27 октября 2026. Продолжение [проверки вертикальной поправки](../las_vertical/REPORT.md). Проверено, помогает ли более общая модель: три поворота и три сдвига, с неизменным масштабом. 0929 остаётся датой сравнения, а не геодезическим эталоном.','',
        f"**На отдельном южном контрольном участке медиана после пробного преобразования ухудшается для {', '.join(worse)}.** Все три контрольных показателя — медиана и P90 обоих направлений — уменьшаются для {', '.join(all_better) or 'ни одной даты'}. Это результат локальной проверки, не подтверждение точности всей сцены.",'',
        'Основное совмещение, исходные LAS, 3DGS и положение BIM сохранены. Пробные матрицы лежат отдельно в `audit.json`; они не включены в просмотрщик и не применены к рабочим облакам.','',
        '## Что сделано','',
        'Найден дополнительный южный участок той же прибрежной линейной конструкции. Он виден во всех семи LAS и отделён от проезда техники. Его фиксированный объём: полоса длиной около 45 м, шириной 1,2 м, высота 2–7,5 м. На выбранном участке 789–1582 исходные точки по датам. Это отдельная пространственная проверка, но не независимая геодезическая съёмка и не другой тип объекта.','',
        'Подгонка использует два других объёма: расширенную маску крыши с верхними гранями существующего здания и прежнюю среднюю береговую полосу. Южный участок не участвует ни в оптимизации, ни в выборе лучшего начального положения. Маски выбраны по цветной геометрии до расчёта ошибок; их координаты сохранены в [regions.json](regions.json).','',
        '![Южный контроль во всех семи датах](bank_south_selection.png)','',
        'На изображении показаны только точки внутри полного XYZ-объёма. Краны и техника исключены расположением и высотными границами масок. Возможны примеси растительности, шум и различия видимых сторон конструкции. Сохраняющийся внешний вид не является доказательством физической неподвижности.','',
        '## Результат на участке, который не подгонялся','',
        'Метрика — среднее двух медиан 3D-расстояния до ближайшей точки: дата → 0929 и 0929 → дата. Меньше означает лучше. Во всех трёх вариантах используются одни и те же точки; после сдвига они повторно по маске не обрезаются.','',
        '| Дата | Исходное положение, м | Только поправка Z по крыше, м | Поворот и сдвиг, м | Изменение относительно исходного, м |',
        '|---|---:|---:|---:|---:|']
    for d in DATES[:-1]:
        before=metric(d,'original')['symmetric_median_m'];z=metric(d,'roof_z_only')['symmetric_median_m'];after=metric(d,'rigid_trial')['symmetric_median_m']
        lines.append(f'| {d} | {before:.3f} | {z:.3f} | {after:.3f} | {after-before:+.3f} |')
    lines+=['| 0929 | — | — | — | Опорная дата сравнения |','',
        'У 0708 все три контрольные метрики лучше исходных, но простой вертикальный сдвиг на этом участке даёт меньшую медиану, чем полный поворот с переносом (0,273 против 0,324 м). Польза добавленных степеней свободы этим контролем не подтверждается.','',
        '![Подгонка на двух участках и проверка на третьем](comparison.png)','',
        'Два левых графика описывают участки подгонки, правый — контроль. Улучшение слева само по себе не подтверждает улучшение всей съёмки. Эти числа не следует смешивать с предыдущими высотными остатками по XY-блокам: здесь другая метрика и новый контрольный участок.','',
        '### Проверка хвостов расстояний','',
        '| Дата | P90 дата → 0929: исходное → пробное, м | P90 0929 → дата: исходное → пробное, м |',
        '|---|---:|---:|']
    for d in DATES[:-1]:
        a=metric(d,'original');b=metric(d,'rigid_trial')
        lines.append(f"| {d} | {a['source_p90_m']:.3f} → {b['source_p90_m']:.3f} | {a['target_p90_m']:.3f} → {b['target_p90_m']:.3f} |")
    lines+=['','P90 — расстояние, не превышаемое 90% точек соответствующего направления. В контрольной оценке нет удаления по расстоянию, робастных весов или повторного выбора точек. Максимумы также сохранены в [comparison.csv](comparison.csv).','',
        '## Насколько устойчив численный результат','',
        'Каждая из шести дат рассчитана из семи положений: вертикальная инициализация по крыше; дополнительно ±0,5 м по X или Y либо ±0,3° вокруг Z. Лучший вариант выбран только по функции ошибки на двух участках подгонки. Диапазон ниже показывает, насколько различается перемещение центра южного участка между семью запусками. Это чувствительность к старту, не доверительный интервал.','',
        '| Дата | Перемещение в центре подгонки X / Y / Z, м | Угол общего поворота, ° | Размах перемещения контроля X / Y / Z, м | Завершение выбранного запуска |',
        '|---|---:|---:|---:|---|']
    for c in chosen:
        shift=' / '.join(f'{v:+.3f}' for v in c['displacement_at_fit_anchor_m']);spread=' / '.join(f'{v:.3f}' for v in c['check_displacement_range_m'])
        lines.append(f"| {c['date']} | {shift} | {np.linalg.norm(c['rotation_vector_degrees']):.3f} | {spread} | {c['chosen_final_status']} |")
    unfinished=[]
    for c in chosen:
        runs=[r for r in audit['runs'] if r['date']==c['date'] and 'iterations' in r]
        count=sum(not r['iterations'][-1]['converged'] for r in runs)
        if count:unfinished.append(f"{c['date']}: {count} из {len(runs)}")
    lines+=['',
        'Не все начальные положения достигли критерия остановки на последнем пороге ('+'; '.join(unfinished)+'). Эти варианты сохранены в аудите и включены в диапазон чувствительности. У 0331 размах перемещения контроля достигает примерно 0,55 м по Y, поэтому единственность решения не подтверждена.']
    lines+=['','`stable_loss` означает, что изменение функции ошибки стало меньше 10⁻⁹. Это численный критерий остановки, а не геодезическая точность. При повороте смещение зависит от места: таблица показывает его в указанном центре подгонки; координаты центра и полные матрицы сохранены в [audit.json](audit.json).','',
        'Для геометрической диагностики отдельно посчитан якобиан расстояний до локальных плоскостей с масштабом вращательных столбцов 100 м. Его численный ранг и сингулярные значения записаны в аудите. Шум, конечные края масок и детали поверхности могут создавать кажущуюся определённость; полный численный ранг не доказывает правильность матрицы. На идеальной плоскости тест показывает ранг 3: она не определяет два сдвига вдоль поверхности и поворот вокруг нормали.','',
        '## Воспроизводимый алгоритм','',
        '1. Проверены SHA-256 семи исходных LAS относительно предыдущего аудита. Использованы прежние локальные координаты с origin [825800, 842100, 0].','2. Применены фиксированные объёмы. В каждом вокселе 0,25 м оставлена первая исходная точка, без усреднения. Эти выборки заморожены до подгонки и контроля; [количество точек](support.csv) сохранено.','3. Выполнен жёсткий ICP по ближайшим 3D-точкам только внутри одноимённых участков. Три порога соответствий: 2 / 1 / 0,5 м. Каждому участку дан одинаковый исходный вес; робастная функция Huber использует порог 0,15 м. Точки за порогом соответствий сохраняют постоянный штраф в функции выбора.','4. Поворот и перенос на каждом шаге вычисляются взвешенным SVD; масштаб строго равен единице, отражение запрещено. Каждый принятый шаг не увеличивает функцию подгонки. До 100 итераций на каждый порог; истории ошибок и причины остановки записаны для всех запусков.','5. Матрица выбрана по подгонке, затем проверена на южном участке без отсечения ошибок. Отдельно сравнивается прежняя вертикальная поправка по крыше. Нормали локальных плоскостей используются только в дополнительной диагностике геометрии, не для итоговой подгонки.','',
        'Предварительная проба подгонки по расстоянию до плоскостей остановилась без подтверждённой сходимости выбранных запусков. Она сохранена в [pointplane_trial.json](pointplane_trial.json) и не используется как итоговая матрица. Воспроизводимый основной расчёт в этом отчёте — ICP по расстояниям между точками.','',
        '## Как это влияет на сравнение с BIM','',
        'Визуально подтянуть два участка к 0929 недостаточно: это может ухудшить третий. Поэтому новые матрицы остаются экспериментом. Они не доказывают ни ошибку BIM, ни физическое перемещение конструкций, ни конкретную деформацию реконструкции. Две береговые полосы также слабо контролируют перемещение вдоль своей оси; оценки условны выбранными узкими объёмами.','',
        'Для рабочей поправки нужны опорные элементы с различными направлениями поверхностей и известной неподвижностью, распределённые по площадке, либо идентифицированные геодезические точки и подтверждённая система высот. До этого можно сравнивать локальные остатки, но нельзя выдавать подобранную матрицу за проверенную абсолютную геопривязку.','',
        '## Файлы и повторный запуск','',
        '[Маска крыши и верхних граней](roof_shell_selection.png) · [средний участок подгонки](bank_mid_selection.png) · [таблица результатов](comparison.csv) · [аудит запусков](audit.json).','',
        '```sh','OPENBLAS_NUM_THREADS=3 OMP_NUM_THREADS=3 .venv/bin/python scripts/check_las_rigid.py',
        '.venv/bin/python scripts/report_las_rigid.py',
        'OPENBLAS_NUM_THREADS=3 OMP_NUM_THREADS=3 .venv/bin/python -m unittest discover -s scripts -p "test_*.py" -v','```','',
        'Три новых численных теста проверяют восстановление известного жёсткого преобразования, убывание функции подгонки, неопределённость плоской поверхности и сохранение больших ошибок на контрольном участке. Полный набор проекта: 19 тестов.','']
    (OUT/'REPORT.md').write_text('\n'.join(lines));print(OUT/'REPORT.md')


if __name__=='__main__':main()
